const item = $('Microsoft Teams Trigger1').first().json ?? {};
const odataId = String(item['@odata.id'] ?? '');
const messageId = String(item.id ?? '').trim();
let chatId = String(item.chatId ?? item.chat?.id ?? '').trim();
if (!chatId && odataId) {
  const m1 = odataId.match(/chats\('([^']+)'\)/i);
  const m2 = odataId.match(/\/chats\/([^/]+)\/messages\//i);
  chatId = m1?.[1] ?? m2?.[1] ?? '';
}
const graphMessageUrl = chatId && messageId
  ? 'https://graph.microsoft.com/v1.0/chats/' + encodeURIComponent(chatId) + '/messages/' + encodeURIComponent(messageId)
  : '';
const graphChatUrl = chatId
  ? 'https://graph.microsoft.com/v1.0/chats/' + encodeURIComponent(chatId)
  : '';
return [{ json: { chatId, messageId, graphMessageUrl, graphChatUrl, hasIds: Boolean(chatId && messageId), startedAt: Date.now() } }];

const cfg = $('Config').first().json;
const ids = $('Extract IDs').first().json;

// Merge liefert [chat, message] kombiniert
const allItems = $input.all();
const chat = allItems[0]?.json ?? {};
const msg = allItems[1]?.json ?? allItems[0]?.json ?? {};

// FIX 08/2026: Graph-Fehler sichtbar machen. Load Full Message laeuft mit
// neverError:true, liefert bei 403/404 also den Fehlerkoerper statt zu
// scheitern. Ohne diese Pruefung ist msg ein Fehlerobjekt, der Text leer,
// hasImages false - und die Nachricht wird als 'empty_text_no_image'
// verworfen. Ein Berechtigungsausfall sah damit exakt aus wie eine leere
// Nachricht und blieb unsichtbar.
const graphFehlerCode = String(msg?.error?.code ?? '');
const graphFehlerText = String(msg?.error?.message ?? '').slice(0, 300);
const hatGraphFehler = Boolean(graphFehlerCode || graphFehlerText)
  || (!msg.id && msg.body === undefined);
// Fehler beim Chat-Abruf blockiert nicht, wird aber protokolliert: chatType
// faellt dann auf den bisherigen Standardwert zurueck.
const chatFehlerCode = String(chat?.error?.code ?? '');

const rawHtml = String(msg.body?.content ?? '');
let text = rawHtml
  .replace(/<!--[\s\S]*?-->/g, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<at[^>]*>.*?<\/at>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|li|tr)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/[\u200B-\u200D\uFEFF\u202A-\u202E]/g, '')
  .replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, 5000);

const fromUserId = String(msg.from?.user?.id ?? msg.from?.application?.id ?? '');
const fromUser = String(msg.from?.user?.displayName ?? msg.from?.application?.displayName ?? '');
const fromType = msg.from?.user ? 'user' : (msg.from?.application ? 'application' : 'unknown');
const botIds = String(cfg.botUserIds ?? '').split(',').map(v => v.trim()).filter(Boolean);

const attachments = Array.isArray(msg.attachments) ? msg.attachments : [];
const hostedContents = Array.isArray(msg.hostedContents) ? msg.hostedContents : [];

// FIX 08/2026: Ein per Strg+V eingefuegtes Bild taucht WEDER in attachments[]
// NOCH in hostedContents[] auf. Graph legt es ausschliesslich als
// <img src=".../messages/<id>/hostedContents/<contentId>/$value"> in den
// HTML-Body. Ohne diese Extraktion war hasImages immer false, der Text nach
// dem Strippen leer und die Nachricht wurde als 'empty_text_no_image'
// kommentarlos verworfen - der Nutzer bekam gar keine Antwort.
const inlineIds = [];
const hostedRe = /hostedContents\/([A-Za-z0-9._~%=+-]+)\/\$value/gi;
let treffer;
while ((treffer = hostedRe.exec(rawHtml)) !== null) {
  const id = treffer[1];
  if (id && !inlineIds.includes(id)) inlineIds.push(id);
}

// Dateianhaenge liefern contentType 'reference' statt eines Bild-MIME-Typs.
// Der Bildcharakter ergibt sich dann nur aus der Dateiendung.
const bildEndung = /\.(png|jpe?g|gif|webp|bmp)$/i;

const normalizedAttachments = [
  ...attachments.map(a => {
    const ct = String(a.contentType ?? '');
    const name = String(a.name ?? '');
    return {
      source: 'attachment',
      id: String(a.id ?? ''),
      name,
      contentType: ct,
      // contentUrl wird vom Subworkflow fuer den SharePoint-Abrufweg gebraucht
      contentUrl: String(a.contentUrl ?? ''),
      isImage: /^image\//i.test(ct) || bildEndung.test(name),
    };
  }),
  ...hostedContents.map(h => ({
    source: 'hostedContent',
    id: String(h.id ?? ''),
    name: 'hosted-image',
    contentType: String(h.contentType ?? 'image/png'),
    contentUrl: '',
    isImage: true,
  })),
  ...inlineIds
    .filter(id => !hostedContents.some(h => String(h.id ?? '') === id))
    .map((id, i) => ({
      source: 'hostedContent',
      id,
      name: 'inline-bild-' + (i + 1),
      contentType: 'image/png',
      contentUrl: '',
      isImage: true,
    })),
];

const hasImages = normalizedAttachments.some(a => a.isImage);

// chatType aus Chat-Response (erster Item vom Merge)
const chatType = String(chat.chatType ?? 'oneOnOne');

const shouldProcess = Boolean(
  !hatGraphFehler &&
  chatType === 'oneOnOne' &&
  fromType === 'user' &&
  !botIds.includes(fromUserId) &&
  (text || hasImages) &&
  ids.chatId && ids.messageId
);

const skipReason = shouldProcess ? '' :
  hatGraphFehler ? ('graph_error' + (graphFehlerCode ? ':' + graphFehlerCode : '')) :
  chatType !== 'oneOnOne' ? 'not_one_on_one' :
  fromType !== 'user' ? 'not_user' :
  botIds.includes(fromUserId) ? 'own_message' :
  (!text && !hasImages) ? 'empty_text_no_image' : 'missing_ids';

return [{ json: {
  chatId: ids.chatId, messageId: ids.messageId, chatType,
  fromUserId, fromUser, fromType,
  isBot: botIds.includes(fromUserId) || fromType !== 'user',
  text, userQuestion: text, shouldProcess, skipReason, hasImages,
  graphFehlerCode, graphFehlerText, chatFehlerCode,
  imageAttachments: normalizedAttachments.filter(a => a.isImage).slice(0, 4),
  jiraBaseUrl: cfg.jiraBaseUrl, source: 'teams'
} }];

const norm = $('Normalize & Sanitize').first().json;
const identity = $input.first().json ?? {};
const allowed = Array.isArray(identity.allowedAudiences) ? identity.allowedAudiences : ['public'];
const isIT = allowed.includes('it_internal');
const userEmail = String(identity.mail || identity.userPrincipalName || '').toLowerCase();
return [{ json: { userQuestion:norm.userQuestion, chatId:norm.chatId, messageId:norm.messageId, hasImages:norm.hasImages, imageAttachments:norm.imageAttachments, isIT, userEmail, allowedAudiences:allowed, givenName:identity.hasSafeFirstName ? String(identity.givenName||'') : '', displayName:norm.fromUser, jiraBaseUrl:norm.jiraBaseUrl, imageInsights:'', source:'teams' } }];

