let raw = String($json.output ?? '').trim();
if (!raw) raw = 'Entschuldigung, ich konnte keine Antwort erzeugen. Bitte wende dich an das IT-Support-Team.';
const leakPatterns = [/systemprompt|system-prompt|system message/i, /allowedAudiences|audienceCsv|it_internal|document_chunks|accountId|eigentumBestaetigt/i, /sk-[a-z0-9]{20,}|bearer\s+ey[a-z0-9._-]+/i];
for (const p of leakPatterns) { if (p.test(raw)) { raw = 'Ich kann diese Frage nicht beantworten. Bitte wende dich an das IT-Support-Team.'; break; } }
// Platzhalter-Links: Markdown-Link ohne echte URL wird auf den reinen Text reduziert,
// damit kein toter Verweis in Teams landet.
raw = raw.replace(/\[([^\]\n]+)\]\(\s*(?!https?:\/\/)[^)\n]*\)/g, '$1');
const insultPattern = /\b(idiot|trottel|dumm|arschloch)\b/i;
if (insultPattern.test(raw)) raw = 'Ich halte mich an einen respektvollen Ton. Wie kann ich dir helfen?';
if (raw.length > 4000) raw = raw.slice(0, 3950) + '\n\n(Antwort gekuerzt)';
let ctx = {};
try { ctx = $('Agent-Eingabe bauen').first().json || {}; } catch (e) {}
return [{ json: { response: raw, replyText: raw, chatId: ctx.chatId || '', source: ctx.source || 'teams' } }];

const item = $input.first().json ?? {};
const raw = String(item.replyText ?? '').trim() || 'Da ist etwas schiefgelaufen.';
const esc = v => String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const safeUrl = v => { const u=String(v??'').trim().replace(/\r/g,'').replace(/\n/g,''); return /^https?:\/\/[^\s<>"']+$/i.test(u)?u:''; };
const fmtInline = value => {
  let text=String(value??''); const prot=[];
  const ph=html=>{ const tok='@@P'+prot.length+'@@'; prot.push({tok,html}); return tok; };
  text=text.replace(/\[([^\]\n]+)\]\s*\(\s*(https?:\/\/[^\s<>"')]+)\s*\)/gi,(m,label,url)=>{ const s=safeUrl(url); return s?ph('<a href="'+esc(s)+'">'+esc(label)+'</a>'):m; });
  text=text.replace(/https?:\/\/[^\s<>"']+/gi,m=>{ const s=safeUrl(m); return s?ph('<a href="'+esc(s)+'">'+esc(s)+'</a>'):m; });
  let out=esc(text).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`\n]+)`/g,'<code>$1</code>');
  for (const p of prot) out=out.split(p.tok).join(p.html);
  return out;
};
const lines=raw.replace(/\r/g,'').split('\n');
const html=[]; let ul=false; let ol=false;

// FIX 08/2026: Nummerierte Listen wurden als <p> gerendert - "1. Text" landete
// als Absatz in Teams statt als Liste. Sichtbar in fast jeder laengeren
// Antwort, besonders bei Ticketlisten. Jetzt <ol>/<li> analog zur bereits
// vorhandenen <ul>-Behandlung. Die Nummer selbst wird entfernt, weil <ol> sie
// selbst erzeugt - sonst stuende dort "1. 1. Text".
const listeSchliessen = () => {
  if (ul) { html.push('</ul>'); ul=false; }
  if (ol) { html.push('</ol>'); ol=false; }
};

for (const src of lines) {
  const line=src.trim(); if(!line) continue;

  const bm=line.match(/^[-*\u2022]\s+(.+)$/);
  if(bm){ if(ol){html.push('</ol>');ol=false;} if(!ul){html.push('<ul>');ul=true;} html.push('<li>'+fmtInline(bm[1])+'</li>'); continue; }

  const om=line.match(/^(\d+)[.)]\s+(.+)$/);
  if(om){ if(ul){html.push('</ul>');ul=false;} if(!ol){html.push('<ol>');ol=true;} html.push('<li>'+fmtInline(om[2])+'</li>'); continue; }

  listeSchliessen();

  const hm=line.match(/^#{1,6}\s+(.+)$/);
  if(hm){html.push('<p><strong>'+fmtInline(hm[1])+'</strong></p>');continue;}
  html.push('<p>'+fmtInline(line)+'</p>');
}
listeSchliessen();
const replyHtml = '<div>'+html.join('')+'</div>';

// Body als fertiger JSON-String fuer Send Node
const graphBody = JSON.stringify({body:{contentType:'html',content:replyHtml}});

return [{ json: { ...item, replyHtml, graphBody } }];

parameters.jsonBody:
={{ {
  "model": "gpt-4o-mini",
  "temperature": 0.6,
  "max_tokens": 180,
  "messages": [
    {"role": "system", "content": "Du bist der IT-Support-Assistent der RWG Rheinland eG im Microsoft-Teams-Chat. Antworte natuerlich, freundlich und persoenlich auf Deutsch in der Du-Form auf Begruessung, Smalltalk oder Dank. Sprich die Person wenn moeglich mit Vornamen an. Halte dich kurz (1-3 Saetze) und wiederhole keine Floskeln. Beziehe dich natuerlich auf einen bisherigen Verlauf, falls vorhanden. Biete bei Bedarf an, bei IT-Themen (Tickets, Probleme, Anleitungen) zu helfen - ohne aufdringlich zu sein. Erfinde keine Fakten und keine Tickets." + ($('Format Memory').first().json.hasMemory ? "\n\nBisheriger Verlauf:\n" + $('Format Memory').first().json.memoryText : "") },
    {"role": "user", "content": "Person: " + ($json.givenName || 'unbekannt') + " (" + ($json.isIT ? 'IT-Team' : 'Fachbereich') + ")\nNachricht: " + ($json.userQuestion || 'Hallo') }
  ]
} }}

parameters.jsCode:
// LLM-Begruessung korrekt auslesen; Fallback nur, wenn wirklich leer.
const content = (($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '').trim();
const replyText = content || 'Hallo! Wie kann ich dir helfen?';
let chatId = '';
try { chatId = $('Greeting-Gate').first().json.chatId || ''; } catch (e) {}
if (!chatId) { try { chatId = $('Build Teams Context').first().json.chatId || ''; } catch (e) {} }
const safe = replyText.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const graphBody = JSON.stringify({ body: { contentType: 'html', content: '<p>' + safe + '</p>' } });
return [{ json: { replyText, graphBody, chatId } }];

// Bild-Insights aus dem Subworkflow: imageInsightsText ist der fertige String.
const item = $input.first().json ?? {};
const imageInsights = item.imageInsightsText || '';
const ctx = $('Greeting-Gate').first().json;
return [{ json: { ...ctx, imageInsights } }];

// Letzte Turns (id desc) chronologisch aufbereiten; Kontext von Build Teams Context durchreichen.
const rows = $('Load Memory').all().map(i => i.json).filter(r => r && r.content);
const chrono = rows.slice().reverse();
const memoryTurns = chrono.map(r => ({ role: r.role, content: String(r.content || '').slice(0, 700) }));
const memoryText = memoryTurns.map(t => (t.role === 'assistant' ? 'Bot' : 'Nutzer') + ': ' + t.content).join('\n');
const btc = $('Build Teams Context').first().json;
return [{ json: { ...btc, memoryText, hasMemory: memoryTurns.length > 0 } }];

// Reply-Text robust ermitteln (Code-Node vertraegt try/catch, Ausdruck nicht).
let replyText = '';
try { replyText = $('Output Guard').first().json.replyText || ''; } catch(e) {}
if (!replyText) { try { replyText = $('Format Greeting').first().json.replyText || ''; } catch(e) {} }
let chatId = '', userText = '', hatBilder = false;
try { const b = $('Build Teams Context').first().json; chatId = b.chatId || ''; userText = b.userQuestion || ''; hatBilder = b.hasImages === true; } catch(e) {}

// FIX 08/2026: Bei Bildnachrichten ohne Text wurde ein leerer Nutzer-Eintrag
// gespeichert. Im Verlauf standen dann Bot-Antworten ohne erkennbare Frage -
// das Gedaechtnis wurde luecken- und dadurch stellenweise unlesbar, was das
// Aufloesen spaeterer Rueckbezuege erschwert. Ein Platzhalter haelt die
// Abfolge Frage/Antwort intakt und sagt dem Modell, was tatsaechlich ankam.
if (!String(userText).trim()) {
  userText = hatBilder ? '[Bild ohne Text]' : '[leere Nachricht]';
}

return [{ json: { chatId, userText, replyText } }];

// Deterministisches Gate statt LLM-Klassifikation: spart einen Modellaufruf je Nachricht
// und kann eine Fachfrage nicht faelschlich als Smalltalk abtun.
const ctx = $input.first().json ?? {};
const q = String(ctx.userQuestion || '').trim();

// Fragezeichen zaehlt vor der Bereinigung, sonst geht es beim Strippen verloren.
const hatFrage = q.includes('?');
const hatTicket = /ssd[\s-]?\d{2,6}/i.test(q);

// FIX 08/2026: Umlaute normalisieren. Das Grussmuster ist umlautfrei notiert
// (tschuess, dankeschoen, schoenes wochenende), der Nutzertext war es nicht.
// "Tschuess" traf, "Tschuess" mit Umlaut fiel durch und loeste einen vollen
// Agentenlauf samt Werkzeugaufruf fuer eine Verabschiedung aus.
const entumlauten = s => String(s)
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss');

// FIX 08/2026, zweiter Anlauf (Beleg: Lauf 102715). Der erste Versuch entfernte
// gezielt Emojis und scheiterte trotzdem: "Tschuess du Nase 👃”" endete auf ein
// typografisches Anfuehrungszeichen, das weder vom Emoji- noch vom
// Interpunktionsmuster erfasst wurde. Statt eine Liste stoerender Zeichen zu
// pflegen, bleiben jetzt nur Buchstaben und Ziffern stehen - Emojis,
// Anfuehrungszeichen, Klammern und Sonderzeichen fallen gemeinsam weg. Sie
// tragen bei einer Verabschiedung ohnehin keine Bedeutung.
const ql = entumlauten(q.toLowerCase())
  .replace(/[^\p{L}\p{N}]+/gu, ' ')
  .trim();
const woerter = ql ? ql.split(' ').filter(Boolean) : [];

// Grenze von vier auf sechs Woerter: Gruesse wie "danke dir schoenes
// wochenende" lagen sonst knapp darueber und loesten einen vollen Agentenlauf aus.
const grussMuster = /^(hallo|hi|hey|moin|servus|guten morgen|guten tag|guten abend|na|danke|vielen dank|danke dir|dankeschoen|besten dank|super|perfekt|klasse|alles klar|ok|okay|passt|verstanden|tschuess|ciao|bis dann|bis morgen|bis spaeter|schoenes wochenende|schoenen feierabend)([ ][a-z]{1,15})*$/;

// Bild ohne Text ist keine Begruessung, sondern eine Anfrage an den Agenten.
const istBegruessung = Boolean(ql)
  && ctx.hasImages !== true
  && !hatFrage
  && !hatTicket
  && woerter.length <= 6
  && grussMuster.test(ql);

return [{ json: { ...ctx, istBegruessung } }];

// Sammelt nur noch Kontext. Die Beschaffung macht der Agent ueber seine Werkzeuge.
const ctx = $('Greeting-Gate').first().json ?? {};
let imageInsights = '';
try { imageInsights = $input.first().json.imageInsights || ''; } catch (e) {}

let currentDateTime = '';
try {
  currentDateTime = $now.setZone('Europe/Berlin').setLocale('de').toFormat("cccc, d. MMMM yyyy, HH:mm 'Uhr'");
} catch (e) {
  try { currentDateTime = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }); } catch (e2) { currentDateTime = ''; }
}

return [{ json: {
  userQuestion: ctx.userQuestion || '',
  chatId: ctx.chatId || '',
  isIT: ctx.isIT === true,
  userEmail: ctx.userEmail || '',
  givenName: ctx.givenName || '',
  memoryText: ctx.memoryText || '',
  hasMemory: ctx.hasMemory === true,
  imageInsights,
  currentDateTime,
  source: 'teams'
} }];
